package com.CV.Oil_Gas.services;
import com.CV.Oil_Gas.dto.*; import com.CV.Oil_Gas.entities.*; import com.CV.Oil_Gas.exceptions.*; import com.CV.Oil_Gas.repositories.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Service @RequiredArgsConstructor @Transactional
public class OperationsService {
 private final WellRepository wellRepository; private final RigRepository rigRepository; private final ProductionReadingRepository productionReadingRepository; private final StorageTankRepository storageTankRepository; private final ShipmentRepository shipmentRepository; private final CustomerRepository customerRepository; private final EquipmentRepository equipmentRepository; private final TechnicianRepository technicianRepository; private final MaintenanceRecordRepository maintenanceRecordRepository; private final InspectionRepository inspectionRepository; private final InspectorRepository inspectorRepository; private final PipelineRepository pipelineRepository; private final OilFieldRepository oilFieldRepository; private final IncidentRepository incidentRepository; private final PersonnelRepository personnelRepository; private final ContractorRepository contractorRepository;
 public ProductionReadingDTO recordProduction(Long wellId,ProductionReadingDTO dto){Well w=wellRepository.findByIdAndIsActiveTrue(wellId).orElseThrow(()->new ResourceNotFoundException("Well not found")); if(!"producing".equalsIgnoreCase(w.getStatus()))throw new BadRequestException("Well must be producing"); if(dto.getOilVolume().signum()<0||dto.getGasVolume().signum()<0||dto.getWaterVolume().signum()<0)throw new BadRequestException("Production volumes cannot be negative"); ProductionReading p=new ProductionReading();p.setReadingDate(dto.getReadingDate());p.setOilVolume(dto.getOilVolume());p.setGasVolume(dto.getGasVolume());p.setWaterVolume(dto.getWaterVolume());p.setWell(w);p=productionReadingRepository.save(p);return ProductionReadingDTO.builder().id(p.getId()).readingDate(p.getReadingDate()).oilVolume(p.getOilVolume()).gasVolume(p.getGasVolume()).waterVolume(p.getWaterVolume()).wellId(w.getId()).build();}
 public WellDTO assignRig(Long wellId,Long rigId){Well w=wellRepository.findByIdAndIsActiveTrue(wellId).orElseThrow(()->new ResourceNotFoundException("Well not found"));Rig r=rigRepository.findByIdAndIsActiveTrue(rigId).orElseThrow(()->new ResourceNotFoundException("Rig not found"));boolean busy=wellRepository.findByIsActiveTrue().stream().anyMatch(x->x.getRig()!=null&&x.getRig().getId().equals(rigId)&&!x.getId().equals(wellId));if(busy)throw new BadRequestException("Rig is already assigned to another active well");w.setRig(r);wellRepository.save(w);return WellDTO.builder().id(w.getId()).wellCode(w.getWellCode()).depth(w.getDepth()).type(w.getType()).status(w.getStatus()).oilFieldId(w.getOilField().getId()).rigId(r.getId()).build();}
 public StorageTankDTO transferToTank(Long tankId,BigDecimal volume){if(volume==null||volume.signum()<=0)throw new BadRequestException("Transfer volume must be positive");StorageTank t=storageTankRepository.findByIdAndIsActiveTrue(tankId).orElseThrow(()->new ResourceNotFoundException("Tank not found"));BigDecimal next=t.getCurrentLevel().add(volume);if(next.compareTo(t.getCapacity())>0)throw new BadRequestException("Transfer exceeds tank capacity");t.setCurrentLevel(next);storageTankRepository.save(t);return StorageTankDTO.builder().id(t.getId()).tankCode(t.getTankCode()).capacity(t.getCapacity()).currentLevel(t.getCurrentLevel()).product(t.getProduct()).oilFieldId(t.getOilField().getId()).build();}
 public ShipmentDTO dispatch(ShipmentDTO dto){StorageTank t=storageTankRepository.findByIdAndIsActiveTrue(dto.getStorageTankId()).orElseThrow(()->new ResourceNotFoundException("Tank not found"));Customer customer=customerRepository.findByIdAndIsActiveTrue(dto.getCustomerId()).orElseThrow(()->new ResourceNotFoundException("Customer not found"));if(dto.getVolume().compareTo(t.getCurrentLevel())>0)throw new BadRequestException("Shipment exceeds tank current level");t.setCurrentLevel(t.getCurrentLevel().subtract(dto.getVolume()));storageTankRepository.save(t);Shipment s=new Shipment();s.setShipmentDate(dto.getShipmentDate());s.setVolume(dto.getVolume());s.setDestination(dto.getDestination());s.setStatus(dto.getStatus());s.setStorageTank(t);s.setCustomer(customer);s=shipmentRepository.save(s);return ShipmentDTO.builder().id(s.getId()).shipmentDate(s.getShipmentDate()).volume(s.getVolume()).destination(s.getDestination()).status(s.getStatus()).storageTankId(t.getId()).customerId(customer.getId()).build();}
 public MaintenanceRecordDTO logMaintenance(MaintenanceRecordDTO dto,String equipmentStatus){Equipment e=equipmentRepository.findByIdAndIsActiveTrue(dto.getEquipmentId()).orElseThrow(()->new ResourceNotFoundException("Equipment not found"));Technician t=technicianRepository.findByIdAndIsActiveTrue(dto.getTechnicianId()).orElseThrow(()->new ResourceNotFoundException("Technician not found"));MaintenanceRecord m=new MaintenanceRecord();m.setMaintenanceDate(dto.getMaintenanceDate());m.setDescription(dto.getDescription());m.setCost(dto.getCost());m.setEquipment(e);m.setTechnician(t);m=maintenanceRecordRepository.save(m);e.setStatus(equipmentStatus);equipmentRepository.save(e);return MaintenanceRecordDTO.builder().id(m.getId()).maintenanceDate(m.getMaintenanceDate()).description(m.getDescription()).cost(m.getCost()).equipmentId(e.getId()).technicianId(t.getId()).build();}
 public List<MaintenanceRecordDTO> maintenanceForEquipment(Long id){return maintenanceRecordRepository.findByEquipmentIdAndIsActiveTrue(id).stream().map(m->MaintenanceRecordDTO.builder().id(m.getId()).maintenanceDate(m.getMaintenanceDate()).description(m.getDescription()).cost(m.getCost()).equipmentId(m.getEquipment().getId()).technicianId(m.getTechnician().getId()).build()).toList();}
 public InspectionDTO scheduleInspection(InspectionDTO dto){if((dto.getWellId()==null)==(dto.getPipelineId()==null))throw new BadRequestException("Provide exactly one of wellId or pipelineId");if(dto.getInspectionDate().isAfter(LocalDate.now().plusDays(90)))throw new BadRequestException("Inspection cannot be scheduled more than 90 days ahead");Inspector i=inspectorRepository.findByIdAndIsActiveTrue(dto.getInspectorId()).orElseThrow(()->new ResourceNotFoundException("Inspector not found"));Inspection x=new Inspection();x.setInspectionDate(dto.getInspectionDate());x.setResult(dto.getResult());x.setNotes(dto.getNotes());x.setInspector(i);if(dto.getWellId()!=null)x.setWell(wellRepository.findByIdAndIsActiveTrue(dto.getWellId()).orElseThrow(()->new ResourceNotFoundException("Well not found")));else x.setPipeline(pipelineRepository.findByIdAndIsActiveTrue(dto.getPipelineId()).orElseThrow(()->new ResourceNotFoundException("Pipeline not found")));x=inspectionRepository.save(x);return InspectionDTO.builder().id(x.getId()).inspectionDate(x.getInspectionDate()).result(x.getResult()).notes(x.getNotes()).wellId(x.getWell()==null?null:x.getWell().getId()).pipelineId(x.getPipeline()==null?null:x.getPipeline().getId()).inspectorId(i.getId()).build();}
 public IncidentDTO reportIncident(IncidentDTO dto){OilField f=oilFieldRepository.findByIdAndIsActiveTrue(dto.getOilFieldId()).orElseThrow(()->new ResourceNotFoundException("Oil field not found"));Personnel p=personnelRepository.findByIdAndIsActiveTrue(dto.getReportedById()).orElseThrow(()->new ResourceNotFoundException("Personnel not found"));if(!p.getOilField().getId().equals(f.getId()))throw new BadRequestException("Reporter is not assigned to this field");Incident i=new Incident();i.setIncidentDate(dto.getIncidentDate());i.setSeverity(dto.getSeverity());i.setDescription(dto.getDescription());i.setStatus(dto.getStatus());i.setOilField(f);i.setReportedBy(p);i=incidentRepository.save(i);return IncidentDTO.builder().id(i.getId()).incidentDate(i.getIncidentDate()).severity(i.getSeverity()).description(i.getDescription()).status(i.getStatus()).oilFieldId(f.getId()).reportedById(p.getId()).build();}
 public List<IncidentDTO> openIncidents(String severity){return incidentRepository.findByStatusIgnoreCaseAndIsActiveTrue("OPEN").stream().filter(i->severity==null||i.getSeverity().equalsIgnoreCase(severity)).map(i->IncidentDTO.builder().id(i.getId()).incidentDate(i.getIncidentDate()).severity(i.getSeverity()).description(i.getDescription()).status(i.getStatus()).oilFieldId(i.getOilField().getId()).reportedById(i.getReportedBy().getId()).build()).toList();}
 public BigDecimal totalOil(Long fieldId,LocalDate start,LocalDate end){oilFieldRepository.findByIdAndIsActiveTrue(fieldId).orElseThrow(()->new ResourceNotFoundException("Oil field not found"));return productionReadingRepository.totalOilByFieldAndDateRange(fieldId,start,end);}
 public List<WellDTO> producingWells(){return wellRepository.findByStatusIgnoreCaseAndIsActiveTrue("PRODUCING").stream().map(w->WellDTO.builder().id(w.getId()).wellCode(w.getWellCode()).depth(w.getDepth()).type(w.getType()).status(w.getStatus()).oilFieldId(w.getOilField().getId()).rigId(w.getRig()==null?null:w.getRig().getId()).build()).toList();}
 public List<StorageTankDTO> tanksAbove90(){return storageTankRepository.findAboveNinetyPercent().stream().map(t->StorageTankDTO.builder().id(t.getId()).tankCode(t.getTankCode()).capacity(t.getCapacity()).currentLevel(t.getCurrentLevel()).product(t.getProduct()).oilFieldId(t.getOilField().getId()).build()).toList();}
 public List<PipelineDTO> pipelinesDueForInspection(){return pipelineRepository.findDueForInspection(LocalDate.now().minusMonths(6)).stream().map(p->PipelineDTO.builder().id(p.getId()).pipelineCode(p.getPipelineCode()).lengthKm(p.getLengthKm()).diameter(p.getDiameter()).status(p.getStatus()).oilFieldId(p.getOilField().getId()).build()).toList();}
 public List<EquipmentDTO> equipmentByMaintenanceCost(){return equipmentRepository.findOrderByMaintenanceCostDesc().stream().map(e->EquipmentDTO.builder().id(e.getId()).name(e.getName()).serialNumber(e.getSerialNumber()).type(e.getType()).status(e.getStatus()).oilFieldId(e.getOilField().getId()).build()).toList();}
 public Map<String,Object> fieldStats(Long fieldId){OilField f=oilFieldRepository.findByIdAndIsActiveTrue(fieldId).orElseThrow(()->new ResourceNotFoundException("Oil field not found"));long wells=wellRepository.findByOilFieldIdAndIsActiveTrue(fieldId).size();BigDecimal total=productionReadingRepository.totalOilByFieldAndDateRange(fieldId,LocalDate.of(1900,1,1),LocalDate.now());long open=incidentRepository.findByOilFieldIdAndIsActiveTrue(fieldId).stream().filter(i->"OPEN".equalsIgnoreCase(i.getStatus())).count();return Map.of("fieldId",f.getId(),"fieldName",f.getName(),"activeWellCount",wells,"totalOilProduction",total,"openIncidentCount",open);}
 public Map<String,Object> contractorStats(Long id){Contractor c=contractorRepository.findByIdAndIsActiveTrue(id).orElseThrow(()->new ResourceNotFoundException("Contractor not found"));return Map.of("contractorId",c.getId(),"contractorName",c.getName(),"rigCount",rigRepository.findByContractorIdAndIsActiveTrue(id).size(),"personnelCount",personnelRepository.findByContractorIdAndIsActiveTrue(id).size());}
}